[AttributeUsage(AttributeTargets.Method, AllowMultiple = false)]
public sealed class RetryTestMethodAttribute : TestMethodAttribute
{
    public int RetryCount { get; set; } = 3;

    public RetryTestMethodAttribute(int retryCount = 3)
    {
        RetryCount = retryCount;
    }
}

public class RetryFixtureLifecycleExtension : IRetryExtension
{
    public int MaxRetryCount(TestContext testContext)
    {
        var method = testContext.TestMethod;
        var attr = method?.GetCustomAttributes(typeof(RetryTestMethodAttribute), false)
                         .OfType<RetryTestMethodAttribute>()
                         .FirstOrDefault();
        return attr?.RetryCount ?? 3;
    }
}

